<template>
  <div class="page-shell guestbook-page"><header class="page-heading"><h1>GUESTBOOK</h1></header>
    <section class="wish-wall surface" aria-label="许愿墙" :data-paused="paused"><header class="section-row"><h2 class="comic">WISH WALL</h2><button v-if="wishes.length" class="secondary-button" type="button" :aria-pressed="paused" @click="paused = !paused">{{ paused ? '播放' : '暂停' }}</button></header><div v-if="loading" class="wall-empty" role="status">加载中…</div><div v-else-if="error" class="wall-empty error-text" role="alert">{{ error }} <button class="text-button" type="button" @click="loadMessages">重试</button></div><div v-else-if="!wishes.length" class="wall-empty">暂无愿望</div><div v-else class="wish-field"><div v-for="(row, lane) in wishRows" :key="lane" class="wish-lane"><div v-for="copy in 2" :key="copy" class="wish-group" :aria-hidden="copy === 2"><span v-for="wish in row" :key="wish.id" class="wish-bubble" :title="`${wish.nickname}：${wish.content}`"><span>{{ wish.content }}</span></span></div></div></div></section>
    <section class="guest-layout"><form class="message-form surface" @submit.prevent="submitMessage"><div class="pill-tabs" aria-label="发布类型"><button v-for="type in messageTypes" :key="type.value" type="button" :class="{ active: form.message_type === type.value }" :aria-pressed="form.message_type === type.value" @click="form.message_type = type.value">{{ type.label }}</button></div><div class="field"><label for="nickname">昵称</label><input id="nickname" v-model.trim="form.nickname" maxlength="80" required autocomplete="nickname" /></div><div class="field"><label for="website">个人主页（可选）</label><input id="website" v-model.trim="form.website" type="url" placeholder="https://" /></div><div class="honeypot" aria-hidden="true"><input v-model="form.company" tabindex="-1" autocomplete="off" aria-label="请留空" /></div><div class="field"><label for="message">{{ isWish ? '愿望' : '留言' }}</label><textarea id="message" v-model.trim="form.content" rows="4" minlength="2" :maxlength="isWish ? 200 : 1000" required></textarea></div><button class="primary-button" :disabled="submitting">{{ submitting ? '提交中…' : isWish ? '发布愿望 ↗' : '发布留言 ↗' }}</button><p v-if="notice" :class="success ? 'success-text' : 'error-text'" role="status">{{ notice }}</p></form>
      <div class="message-list"><header class="section-row"><h2 class="comic">MESSAGES</h2><span class="muted">{{ messages.length }}</span></header><div v-if="loading" class="state-card">加载中…</div><div v-else-if="error" class="state-card error">{{ error }}</div><div v-else-if="!messages.length" class="state-card">暂无留言</div><article v-for="message in messages" :key="message.id" class="message-card surface"><div class="message-author"><a v-if="message.website" :href="message.website" target="_blank" rel="noopener noreferrer">{{ message.nickname }}</a><strong v-else>{{ message.nickname }}</strong><time>{{ formatDate(message.created_at) }}</time></div><p>{{ message.content }}</p><div v-if="message.admin_reply" class="reply"><small>站长回复</small><p>{{ message.admin_reply }}</p></div></article></div>
    </section>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { createGuestbookMessage, getGuestbook } from '../api/content';
import { apiError, formatDate } from '../utils/format';
const messageTypes = [{ value: 'message', label: '留言' }, { value: 'wish', label: '许愿' }];
const form = reactive({ nickname: '', website: '', content: '', company: '', message_type: 'message' });
const allMessages = ref([]), loading = ref(true), submitting = ref(false), notice = ref(''), success = ref(false), error = ref(''), paused = ref(false);
const isWish = computed(() => form.message_type === 'wish');
const wishes = computed(() => allMessages.value.filter((message) => message.message_type === 'wish').slice(0, 40));
const messages = computed(() => allMessages.value.filter((message) => message.message_type !== 'wish'));
const wishRows = computed(() => { const count = Math.min(3, wishes.value.length); return Array.from({ length: count }, (_, i) => wishes.value.filter((_, index) => index % count === i)); });
async function loadMessages() { loading.value = true; error.value = ''; try { allMessages.value = (await getGuestbook()).data; } catch { error.value = '留言加载失败。'; } finally { loading.value = false; } }
async function submitMessage() { submitting.value = true; notice.value = ''; if (isWish.value && form.content.length > 200) { notice.value = '愿望最多 200 字。'; success.value = false; submitting.value = false; return; } try { const { data } = await createGuestbookMessage({ ...form }); notice.value = data.detail; success.value = true; form.content = ''; } catch (error) { notice.value = apiError(error, '提交失败，请稍后重试。'); success.value = false; } finally { submitting.value = false; } }
onMounted(loadMessages);
</script>
